#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    cin >> m;
    vector<long long> e(m);
    for (int i = 0; i < m; i++) cin >> e[i];

    long long total = 0, odd = 0;
    for (long long v = 1; v <= m + 1; v++) total ^= v;
    for (long long i = 1; i < m; i += 2) odd ^= e[i];
    long long cur = total ^ odd;
    cout << cur;
    for (long long i = 0; i < m; i++) {
        cur ^= e[i];
        cout << " " << cur;
    }
    cout << "\n";

    return 0;
}

